preConditionHook:
// THE FINAL FLAG -- a named Brooks setup, so the parts are inlined rather than
// referenced, as the corpus does with every composite. After a trend has run
// for many bars, a mostly-horizontal pause showing TWO-SIDED trading is a
// candidate for the trend's last flag.
//
// V07-01 wins the definition: it is the only source that reduces 'final flag'
// to something PROSPECTIVE -- a bar-overlap fraction after an extended trend
// -- instead of the retrospective label VP1-32 correctly calls circular.
// T03-11 contributes the flag's minimum length (6 bars) and V07-06 the
// opposite extreme (a one- or two-bar pause after a spike still counts);
// flagBars 8 sits inside the book's usual 5-10. V07-06's 10-20 bar retest
// expectation is guidance, not a condition.
//
// TWO-SIDED TRADING IS MEASURED AS OVERLAP: a bar counts when it overlaps the
// bar before it by at least overlapThreshold of THAT bar's range, and at least
// minOverlapFraction of the window's bars must count. Deliberately NOT merged
// with a range/ATR width test, which is a different reading of horizontal, and
// not the same as OverlappingBarRun, which demands EVERY pair overlap. The
// count is compared against a fraction of the window rather than divided by
// it: no division, so no divide-by-zero at flagBars 0.
//
// The twin uses MinList / MaxList, ACCEPTED for tick-grid PRICE operands,
// which bar extremes are; the plain ternary stand-in here is exact for the
// same reason (the operands differ by 0 or by at least one tick, 1e9-1e11x the
// relational tolerance). The clamp at zero on a gap is an if rather than
// MaxList(0, ...) because 0 against a price DIFFERENCE is a computed operand,
// outside their accepted scope. Same arrangement as AverageBarOverlap;
// <algorithm> is not among the emitted includes, so no std::min / std::max.
//
// ALWAYS-IN DIRECTION, the standing corpus decision, inlined: the direction
// flips on consecutiveBars consecutive STRONG TREND BARS -- body at least
// bodyFraction of the range, both tails no more than tailFraction -- holds
// until the opposite flip, and is undefined until the first flip. aiBars is
// the trend's age, 0 on the flip bar. The pair of that counter and its
// threshold is TrendDurationBars, an AND-able pane in its own right; this rule
// carries its own copy because a named setup is one rule.
//
// SAME on both sides: the flag is a context, not a direction.
//
// Deepest bar touched: flagBars (the overlap pair reads high[flagBars]), or
// consecutiveBars - 1 if that is larger.
allBull = true;
allBear = true;
for (int k = 0; k < (int)consecutiveBars; ++k) {
    rng = high[k] - low[k];
    if (el_le(close[k], open[k])) allBull = false;
    if (el_lt(close[k] - open[k], bodyFraction * rng)) allBull = false;
    if (el_gt(high[k] - close[k], tailFraction * rng)) allBull = false;
    if (el_gt(open[k] - low[k], tailFraction * rng)) allBull = false;
    if (el_ge(close[k], open[k])) allBear = false;
    if (el_lt(open[k] - close[k], bodyFraction * rng)) allBear = false;
    if (el_gt(close[k] - low[k], tailFraction * rng)) allBear = false;
    if (el_gt(high[k] - open[k], tailFraction * rng)) allBear = false;
}
flipped = false;
if (allBull && aiDir != 1) {
    aiDir = 1;
    aiBars = 0;
    flipped = true;
}
if (allBear && aiDir != -1 && flipped == false) {
    aiDir = -1;
    aiBars = 0;
    flipped = true;
}
if (flipped == false) aiBars = aiBars + 1;
ovCount = 0;
for (int k = 0; k < (int)flagBars; ++k) {
    ovBar = (high[k] < high[k + 1] ? high[k] : high[k + 1])
            - (low[k] > low[k + 1] ? low[k] : low[k + 1]);
    if (el_lt(ovBar, 0.0)) ovBar = 0.0;
    if (el_ge(ovBar, overlapThreshold * (high[k + 1] - low[k + 1]))) ovCount = ovCount + 1;
}
isCandidate = (aiDir != 0) && ((double)aiBars >= minTrendBars) && el_ge((double)ovCount, minOverlapFraction * flagBars);
